package net.atlasauth.pca.fhe

import com.google.gson.JsonArray
import com.google.gson.JsonParser
import java.io.InputStreamReader
import java.nio.file.Files
import java.nio.file.Paths
import java.util.zip.GZIPInputStream
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Assume.assumeTrue
import org.junit.Before
import org.junit.Test

/** Replays the node-seal corpus (generated by CI, never committed) through the Kotlin face and runs a native round trip. */
class FheTest {
    private val required = java.lang.Boolean.getBoolean("pca.fhe.required")

    @Before fun native() {
        val ok = Fhe.available()
        if (required) assertTrue("libsealc must load (-Dpca.sealc.lib)", ok)
        assumeTrue("libsealc not available", ok)
    }

    private fun longs(a: JsonArray) = LongArray(a.size()) { a[it].asLong }

    private fun policy(kappa: Double, budget: Double): FheRiskPolicy {
        val w = doubleArrayOf(0.25, 0.2, 0.2, 0.2, 0.1, 0.05)
        return FheRiskPolicy(1000, 6, LongArray(6) { Math.round(w[it] * 1000) }, LongArray(6) { Math.round(kappa * w[it] * 1000) }, Math.round(budget * 1e6), kappa)
    }

    @Test fun evaluatesTheReferenceCiphertextsToTheReferenceResults() {
        val path = System.getProperty("pca.fhe.corpus", "")
        if (path.isEmpty()) { if (required) fail("pca.fhe.corpus must point at the node-seal corpus"); assumeTrue("no corpus", false) }
        val root = InputStreamReader(GZIPInputStream(Files.newInputStream(Paths.get(path)))).use { JsonParser.parseReader(it).asJsonObject }
        assertEquals(Fhe.POLY_MODULUS_DEGREE, root.getAsJsonObject("seal").get("polyModulusDegree").asInt)
        assertEquals(Fhe.PLAIN_MODULUS, root.getAsJsonObject("seal").get("plainModulus").asLong)
        val cases = root.getAsJsonArray("cases")
        assertTrue(cases.size() >= 6)
        val keys = FheEvalKeys(root.get("publicKey").asString, root.get("galoisKeys").asString)
        for (e in cases) {
            val c = e.asJsonObject
            val p = c.getAsJsonObject("policy")
            val pol = FheRiskPolicy(p.get("scale").asLong, p.get("dim").asLong, longs(p.getAsJsonArray("weightsScaled")),
                longs(p.getAsJsonArray("kappaWeightsScaled")), p.get("budgetScaled").asLong, p.get("kappa").asDouble)
            val g = Fhe.evalRiskGate(keys, c.get("encInputs").asString, pol)
            val name = c.get("name").asString
            // deterministic evaluation: byte-equal once both are re-saved uncompressed
            assertEquals(name, Fhe.canonicalCipher(c.get("encRiskRaw").asString), Fhe.canonicalCipher(g.encRiskRaw))
            assertEquals(name, Fhe.canonicalCipher(c.get("encSlack").asString), Fhe.canonicalCipher(g.encSlack))
        }
    }

    @Test fun nativeRoundTripMatchesPlaintextArithmetic() {
        val keys = Fhe.keygen()
        val cases = listOf(Triple(longArrayOf(100, 900, 100, 100, 100, 100), 1.0, 0.6), Triple(longArrayOf(1000, 1000, 1000, 1000, 1000, 1000), 1.0, 0.5), Triple(LongArray(6), 1.5, 0.25))
        for ((x, kappa, budget) in cases) {
            val p = policy(kappa, budget)
            val g = Fhe.evalRiskGate(keys.evalKeys, Fhe.encryptRiskInputs(keys.publicKey, x), p)
            val raw = (0 until 6).sumOf { p.weightsScaled[it] * x[it] }
            val slack = p.budgetScaled - (0 until 6).sumOf { p.kappaWeightsScaled[it] * x[it] }
            assertEquals(FheVerdict(raw, slack, slack >= 0), Fhe.decryptVerdict(keys.secretKey, g, p))
        }
    }

    @Test fun wrongKeyFailsClosed() {
        val a = Fhe.keygen(); val b = Fhe.keygen()
        val p = policy(1.0, 0.6)
        val g = Fhe.evalRiskGate(a.evalKeys, Fhe.encryptRiskInputs(a.publicKey, longArrayOf(1, 2, 3, 4, 5, 6)), p)
        try { Fhe.decryptVerdict(b.secretKey, g, p); fail("a wrong secret key must not open the verdict") } catch (e: IllegalStateException) { assertTrue(e.message!!.contains("noise budget")) }
    }
}
